import{_ as a,o as r,c as o,ao as t}from"./chunks/framework.Bzbl_aN3.js";const g=JSON.parse('{"title":"Bibliography","description":"","frontmatter":{},"headers":[],"relativePath":"99-bibliography.md","filePath":"99-bibliography.md","lastUpdated":null}'),i={name:"99-bibliography.md"};function n(s,e,l,d,m,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="bibliography" tabindex="-1">Bibliography <a class="header-anchor" href="#bibliography" aria-label="Permalink to &quot;Bibliography {#bibliography}&quot;">​</a></h1><p>The works cited in this documentation. Each page cites them with the key of the entry in <code>docs/src/refs.bib</code>, for example <code>[Walker2022](@cite)</code>. The experimental data themselves come from the ThermoML Archive of NIST/TRC and from the articles it indexes; see <a href="/ThermophysicalDB.jl/previews/PR5/40-about-data#40-about-data">About the data</a>.</p><ul><li><p><a id="Belsley1980"></a> Belsley, D. A.; Kuh, E. and Welsch, R. E. (1980). <em>Regression Diagnostics: Identifying Influential Data and Sources of Collinearity</em> (John Wiley &amp; Sons, New York).</p></li><li><p><a id="Callen1985"></a> Callen, H. B. (1985). <em>Thermodynamics and an Introduction to Thermostatistics</em>. 2 Edition (John Wiley &amp; Sons, New York).</p></li><li><p><a id="Chirico2003"></a> Chirico, R. D.; Frenkel, M.; Diky, V. V.; Marsh, K. N. and Wilhoit, R. C. (2003). <em>ThermoML: An XML-based approach for storage and exchange of experimental and critically evaluated thermophysical and thermochemical property data. 2. Uncertainties</em>. <a href="https://doi.org/10.1021/je034088i" target="_blank" rel="noreferrer">Journal of Chemical &amp; Engineering Data <strong>48</strong>, 1344–1359</a>.</p></li><li><p><a id="Cook1977"></a> Cook, R. D. (1977). <em>Detection of influential observation in linear regression</em>. <a href="https://doi.org/10.1080/00401706.1977.10489493" target="_blank" rel="noreferrer">Technometrics <strong>19</strong>, 15–18</a>.</p></li><li><p><a id="Efron2007"></a> Efron, B. (2007). <em>Size, power and false discovery rates</em>. <a href="https://doi.org/10.1214/009053606000001460" target="_blank" rel="noreferrer">The Annals of Statistics <strong>35</strong>, 1351–1377</a>. Reference details typed from memory; please verify before release.</p></li><li><p><a id="Fischler1981"></a> Fischler, M. A. and Bolles, R. C. (1981). <em>Random sample consensus: a paradigm for model fitting with applications to image analysis and automated cartography</em>. <a href="https://doi.org/10.1145/358669.358692" target="_blank" rel="noreferrer">Communications of the ACM <strong>24</strong>, 381–395</a>.</p></li><li><p><a id="Frenkel2003"></a> Frenkel, M.; Chirico, R. D.; Diky, V.; Dong, Q.; Frenkel, S.; Franchois, P. R.; Marsh, K. N.; Wilhoit, R. C.; Embry, D. L. and Teague, T. L. (2003). <em>ThermoML: An XML-based approach for storage and exchange of experimental and critically evaluated thermophysical and thermochemical property data. 1. Experimental data</em>. <a href="https://doi.org/10.1021/je025645o" target="_blank" rel="noreferrer">Journal of Chemical &amp; Engineering Data <strong>48</strong>, 2–13</a>.</p></li><li><p><a id="Frenkel2006"></a> Frenkel, M.; Chirico, R. D.; Diky, V.; Dong, Q.; Marsh, K. N.; Dymond, J. H.; Wakeham, W. A.; Stein, S. E.; Königsberger, E. and Goodwin, A. R. (2006). <em>XML-based IUPAC standard for experimental, predicted, and critically evaluated thermodynamic property data storage and capture (ThermoML) (IUPAC Recommendations 2006)</em>. <a href="https://doi.org/10.1351/pac200678030541" target="_blank" rel="noreferrer">Pure and Applied Chemistry <strong>78</strong>, 541–612</a>.</p></li><li><p><a id="Gross2001"></a> Gross, J. and Sadowski, G. (2001). <em>Perturbed-chain SAFT: An equation of state based on a perturbation theory for chain molecules</em>. <a href="https://doi.org/10.1021/ie0003887" target="_blank" rel="noreferrer">Industrial &amp; Engineering Chemistry Research <strong>40</strong>, 1244–1260</a>.</p></li><li><p><a id="Grubbs1969"></a> Grubbs, F. E. (1969). <em>Procedures for detecting outlying observations in samples</em>. <a href="https://doi.org/10.1080/00401706.1969.10490657" target="_blank" rel="noreferrer">Technometrics <strong>11</strong>, 1–21</a>.</p></li><li><p><a id="Kunz2012"></a> Kunz, O. and Wagner, W. (2012). <em>The GERG-2008 wide-range equation of state for natural gases and other mixtures: An expansion of GERG-2004</em>. <a href="https://doi.org/10.1021/je300655b" target="_blank" rel="noreferrer">Journal of Chemical &amp; Engineering Data <strong>57</strong>, 3032–3091</a>.</p></li><li><p><a id="Lafitte2013"></a> Lafitte, T.; Apostolakou, A.; Avendaño, C.; Galindo, A.; Adjiman, C. S.; Müller, E. A. and Jackson, G. (2013). <em>Accurate statistical associating fluid theory for chain molecules formed from Mie segments</em>. <a href="https://doi.org/10.1063/1.4819786" target="_blank" rel="noreferrer">The Journal of Chemical Physics <strong>139</strong>, 154504</a>.</p></li><li><p><a id="Leys2013"></a> Leys, C.; Ley, C.; Klein, O.; Bernard, P. and Licata, L. (2013). <em>Detecting outliers: Do not use standard deviation around the mean, use absolute deviation around the median</em>. Journal of Experimental Social Psychology <strong>49</strong>, 764–766.</p></li><li><p><a id="Peng1976"></a> Peng, D.-Y. and Robinson, D. B. (1976). <em>A new two-constant equation of state</em>. <a href="https://doi.org/10.1021/i160057a011" target="_blank" rel="noreferrer">Industrial &amp; Engineering Chemistry Fundamentals <strong>15</strong>, 59–64</a>.</p></li><li><p><a id="Rosner1983"></a> Rosner, B. (1983). <em>Percentage points for a generalized ESD many-outlier procedure</em>. Technometrics <strong>25</strong>, 165–172.</p></li><li><p><a id="Rousseeuw1984"></a> Rousseeuw, P. J. (1984). <em>Least median of squares regression</em>. Journal of the American Statistical Association <strong>79</strong>, 871–880.</p></li><li><p><a id="RousseeuwLeroy1987"></a> Rousseeuw, P. J. and Leroy, A. M. (1987). <em>Robust Regression and Outlier Detection</em> (John Wiley &amp; Sons, New York).</p></li><li><p><a id="Soave1972"></a> Soave, G. (1972). <em>Equilibrium constants from a modified Redlich–Kwong equation of state</em>. <a href="https://doi.org/10.1016/0009-2509(72)80096-4" target="_blank" rel="noreferrer">Chemical Engineering Science <strong>27</strong>, 1197–1203</a>.</p></li><li><p><a id="Span1996"></a> Span, R. and Wagner, W. (1996). <em>A new equation of state for carbon dioxide covering the fluid region from the triple-point temperature to 1100 K at pressures up to 800 MPa</em>. <a href="https://doi.org/10.1063/1.555991" target="_blank" rel="noreferrer">Journal of Physical and Chemical Reference Data <strong>25</strong>, 1509–1596</a>.</p></li><li><p><a id="WagnerPruss2002"></a> Wagner, W. and Pruß, A. (2002). <em>The IAPWS formulation 1995 for the thermodynamic properties of ordinary water substance for general and scientific use</em>. <a href="https://doi.org/10.1063/1.1461829" target="_blank" rel="noreferrer">Journal of Physical and Chemical Reference Data <strong>31</strong>, 387–535</a>.</p></li><li><p><a id="Walker2022"></a> Walker, P. J.; Yew, H.-W. and Riedemann, A. (2022). <em>Clapeyron.jl: An extensible, open-source fluid thermodynamics toolkit</em>. <a href="https://doi.org/10.1021/acs.iecr.2c00326" target="_blank" rel="noreferrer">Industrial &amp; Engineering Chemistry Research <strong>61</strong>, 7130–7153</a>.</p></li><li><p><a id="JCGM100"></a> JCGM Working Group 1 (2008). <a href="https://doi.org/10.59161/JCGM100-2008E" target="_blank" rel="noreferrer"><em>Evaluation of measurement data — Guide to the expression of uncertainty in measurement</em></a>. Technical Report JCGM 100:2008 (<a href="https://doi.org/10.59161/JCGM100-2008E" target="_blank" rel="noreferrer">Joint Committee for Guides in Metrology, Bureau International des Poids et Mesures</a>).</p></li><li><p><a id="NISTThermoMLArchive"></a> NIST Thermodynamics Research Center (TRC) (2020). <a href="https://data.nist.gov/od/id/mds2-2422" target="_blank" rel="noreferrer"><em>ThermoML/Data Archive</em></a>. Dataset, version 2020-09-30. National Institute of Standards and Technology. <a href="https://doi.org/10.18434/mds2-2422" target="_blank" rel="noreferrer"><code>https://doi.org/10.18434/mds2-2422</code></a>.</p></li></ul>',3)])])}const c=a(i,[["render",n]]);export{g as __pageData,c as default};
